/// Release only a list spine whose elements contain no Roc references.
pub fn RocListSpineRelease(comptime ListType: type) type {
    return struct {
        pub fn release(value: ListType, roc_host: *RocHost) void {
            value.decref(roc_host);
        }
    };
}

